+   if(i){await new Promise(resolve=>window.setTimeout(resolve,400*i));url.searchParams.set('_textureRetry',`${i}-${Date.now()}`);}
+   try{return await attempt(i?url.href:source);}catch(error){lastError=error;}
+  }
+  throw lastError;
+ }finally{release();}
